import sys


def already_sorted(batch):
    for i in range(len(batch) - 1):
        if batch[i] > batch[i + 1]:
            return False
    return True


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    result = already_sorted(values)
    print(result)


main()
